contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint seed) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (seed)); require(seed <= 1000000000000000000000000000000);
        require(true);
        // contract must hold some ether from an unrelated prior deposit so a no-op
        // withdrawal could in principle have had an effect if it misbehaved
        require(address(this).balance >= seed);
        c.deposit{value: seed}(); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        // this test contract has deposited seed, so credit > 0; first withdraw it fully
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint contractBalMid = address(c).balance;
        uint testBalMid = address(this).balance;
        // now credit is zero: withdrawAll acts as a non-depositor call
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == contractBalMid && address(this).balance == testBalMid && contractBalMid + testBalMid == contractBalBefore + testBalBefore);
    }
    receive() external payable {}
}

