// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 seed) internal {
        seed = bound(seed, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        vm.assume(address(this).balance >= seed);
        try c.deposit{value: seed}() {} catch { return; }
        uint contractBalBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint contractBalMid = address(c).balance;
        uint testBalMid = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == contractBalMid && address(this).balance == testBalMid && contractBalMid + testBalMid == contractBalBefore + testBalBefore);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
